стовый режим. Деньги не списываются.':'Оплата через ЮKassa.'):'Онлайн-оплата пока не подключена; заказ можно согласовать с магазином.' ?></p></form><?php endif ?></div><aside class="g-summary"><?php $summary($quote);if($path==='cart'): ?><form method="get"><label>Получение<select name="shipping"><option value="delivery" <?= $shipping==='delivery'?'selected':'' ?>>Доставка · <?= Shop::money((int)$s['shipping_cost']) ?></option><?php if($s['pickup_address']): ?><option value="pickup" <?= $shipping==='pickup'?'selected':'' ?>>Самовывоз · бесплатно</option><?php endif ?></select></label><label>Промокод<input name="promo" maxlength="40" value="<?= $e($promo) ?>"></label><button>Рассчитать</button></form><p></p><?php if(!$quote['issues']&&empty($options['error'])): ?><a class="g-button" href="/checkout/?<?= $e(http_build_query(compact('shipping','promo'))) ?>">К оформлению <span>↗</span></a><?php endif;else: foreach($quote['items']as $i): ?><p><?= $e($i['product_title'].' / '.$i['title']) ?> × <?= $i['quantity'] ?></p><?php endforeach;endif ?></aside></div><?php endif;
